"""Losslessly compact GDSII files generated by this repository.

The fabrication writers encode binary rasters as axis-aligned rectangular
BOUNDARY elements. This utility preserves the library hierarchy (including
AREFs) and merges vertically touching rectangles with identical x extents in
each structure. It is intended for GDS files written by this repository; it
keeps unsupported/non-rectangular elements unchanged.
"""

from __future__ import annotations

import argparse
from collections.abc import Iterator
from pathlib import Path
import struct
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

from export_fabrication_patterns import (
    _gds_ascii,
    _gds_dates,
    _gds_real8,
    _gds_record,
    _write_gds_structure_header,
)


HEADER = 0x00
BGNLIB = 0x01
LIBNAME = 0x02
UNITS = 0x03
BGNSTR = 0x05
STRNAME = 0x06
ENDSTR = 0x07
BOUNDARY = 0x08
LAYER = 0x0D
DATATYPE = 0x0E
XY = 0x10
ENDEL = 0x11
ENDLIB = 0x04


class Structure:
    def __init__(self, name: str) -> None:
        self.name = name
        self.rectangles: list[tuple[int, int, int, int, int, int]] = []
        self.raw_elements: list[list[bytes]] = []


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Losslessly compact repository-generated raster GDSII files.")
    parser.add_argument("input_gds", type=Path, help="Existing GDSII file generated by this repository.")
    parser.add_argument("--output", type=Path, default=None, help="Output path; defaults to <input>_compact.gds.")
    return parser.parse_args()


def _records(path: Path) -> Iterator[tuple[int, int, bytes, bytes]]:
    with path.open("rb") as fh:
        while True:
            header = fh.read(4)
            if not header:
                return
            if len(header) != 4:
                raise ValueError("truncated GDS record header")
            length, record_type, data_type = struct.unpack(">HBB", header)
            if length < 4 or length % 2:
                raise ValueError("invalid GDS record length")
            payload = fh.read(length - 4)
            if len(payload) != length - 4:
                raise ValueError("truncated GDS record payload")
            yield record_type, data_type, payload, header + payload


def _decode_string(payload: bytes) -> str:
    return payload.rstrip(b"\x00").decode("ascii")


def _rectangle_from_boundary(records: list[tuple[int, int, bytes, bytes]]) -> tuple[int, int, int, int, int, int] | None:
    layer = datatype = None
    points: list[tuple[int, int]] | None = None
    for record_type, _data_type, payload, _raw in records:
        if record_type == LAYER:
            layer = struct.unpack(">h", payload)[0]
        elif record_type == DATATYPE:
            datatype = struct.unpack(">h", payload)[0]
        elif record_type == XY:
            values = struct.unpack(f">{len(payload) // 4}i", payload)
            points = list(zip(values[::2], values[1::2]))
    if layer is None or datatype is None or points is None or len(points) != 5 or points[0] != points[-1]:
        return None
    x_values = {point[0] for point in points[:-1]}
    y_values = {point[1] for point in points[:-1]}
    if len(x_values) != 2 or len(y_values) != 2:
        return None
    x0, x1 = sorted(x_values)
    y0, y1 = sorted(y_values)
    if x0 == x1 or y0 == y1:
        return None
    for (xa, ya), (xb, yb) in zip(points, points[1:]):
        if xa != xb and ya != yb:
            return None
    return x0, x1, y0, y1, layer, datatype


def _parse_structures(path: Path) -> list[Structure]:
    records = list(_records(path))
    structures: list[Structure] = []
    index = 0
    while index < len(records):
        record_type, _data_type, _payload, _raw = records[index]
        if record_type != BGNSTR:
            index += 1
            continue
        if index + 1 >= len(records) or records[index + 1][0] != STRNAME:
            raise ValueError("GDS structure is missing STRNAME")
        structure = Structure(_decode_string(records[index + 1][2]))
        index += 2
        while index < len(records) and records[index][0] != ENDSTR:
            element: list[tuple[int, int, bytes, bytes]] = []
            while index < len(records):
                element.append(records[index])
                index += 1
                if element[-1][0] == ENDEL:
                    break
                if element[-1][0] == ENDSTR:
                    raise ValueError("unterminated GDS element")
            if not element:
                continue
            if element[0][0] == BOUNDARY:
                rectangle = _rectangle_from_boundary(element)
                if rectangle is not None:
                    structure.rectangles.append(rectangle)
                else:
                    structure.raw_elements.append([record[3] for record in element])
            else:
                structure.raw_elements.append([record[3] for record in element])
        if index >= len(records):
            raise ValueError("GDS structure is missing ENDSTR")
        structures.append(structure)
        index += 1
    if not structures:
        raise ValueError("no GDS structures found")
    return structures


def iter_merged_rectangles(rectangles: list[tuple[int, int, int, int, int, int]]) -> Iterator[tuple[int, int, int, int, int, int]]:
    """Merge vertically touching rectangles having the same layer/x extent."""

    active: dict[tuple[int, int, int, int], tuple[int, int]] = {}
    for x0, x1, y0, y1, layer, datatype in sorted(rectangles, key=lambda item: (item[2], item[3], item[0], item[1], item[4], item[5])):
        key = x0, x1, layer, datatype
        previous = active.get(key)
        if previous is not None and previous[1] == y0:
            active[key] = previous[0], y1
            continue
        if previous is not None:
            yield x0, x1, previous[0], previous[1], layer, datatype
        active[key] = y0, y1
    for (x0, x1, layer, datatype), (y0, y1) in active.items():
        yield x0, x1, y0, y1, layer, datatype


def _write_db_rectangle(fh, rectangle: tuple[int, int, int, int, int, int]) -> None:
    x0, x1, y0, y1, layer, datatype = rectangle
    points = [(x0, y0), (x1, y0), (x1, y1), (x0, y1), (x0, y0)]
    xy_values = [coordinate for point in points for coordinate in point]
    fh.write(_gds_record(0x0800, 0x00))
    fh.write(_gds_record(0x0D02, 0x02, struct.pack(">h", layer)))
    fh.write(_gds_record(0x0E02, 0x02, struct.pack(">h", datatype)))
    fh.write(_gds_record(0x1003, 0x03, struct.pack(f">{len(xy_values)}i", *xy_values)))
    fh.write(_gds_record(0x1100, 0x00))


def compact_generated_gds(input_gds: Path, output_gds: Path) -> tuple[int, int]:
    """Write compact GDS, returning input and output rectangle counts."""

    structures = _parse_structures(input_gds)
    input_rectangles = sum(len(structure.rectangles) for structure in structures)
    output_gds.parent.mkdir(parents=True, exist_ok=True)
    output_rectangles = 0
    with output_gds.open("wb") as fh:
        fh.write(_gds_record(0x0000, 0x02, struct.pack(">h", 600)))
        fh.write(_gds_record(0x0102, 0x02, _gds_dates()))
        fh.write(_gds_record(0x0206, 0x06, _gds_ascii("GRATING_MASKS")))
        fh.write(_gds_record(0x0305, 0x05, _gds_real8(1e-6) + _gds_real8(1e-9)))
        for structure in structures:
            _write_gds_structure_header(fh, structure.name)
            for rectangle in iter_merged_rectangles(structure.rectangles):
                _write_db_rectangle(fh, rectangle)
                output_rectangles += 1
            for element in structure.raw_elements:
                for raw_record in element:
                    fh.write(raw_record)
            fh.write(_gds_record(0x0700, 0x00))
        fh.write(_gds_record(0x0400, 0x00))
    return input_rectangles, output_rectangles


def main() -> int:
    args = parse_args()
    output = args.output or args.input_gds.with_name(f"{args.input_gds.stem}_compact.gds")
    input_rectangles, output_rectangles = compact_generated_gds(args.input_gds, output)
    original_size = args.input_gds.stat().st_size
    compact_size = output.stat().st_size
    reduction = 100.0 * (1.0 - compact_size / original_size) if original_size else 0.0
    print(f"Wrote {output}")
    print(f"Rectangles: {input_rectangles:,} -> {output_rectangles:,}")
    print(f"GDS size: {original_size / 1024**2:.2f} -> {compact_size / 1024**2:.2f} MiB ({reduction:.1f}% smaller)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
